export const extendedIndicators=entries;
export const indicatorByName=Object.fromEntries(entries.map(x=>[x.name,x]));
export const extendedNames=entries.map(x=>x.name);
if(typeof window!=='undefined')window.SnaapIndicatorCatalog={extendedIndicators,indicatorByName};
